/**
 * Twins of the trending-agenda family of group B reads (plan 10.11 section 4): pure functions over in-memory row sets that
 * return what the plpgsql / SQL function returns, held to golden output from a scratch Postgres (`__tests__/golden.test.ts`,
 * generated by `api/scripts/groupb/gen_golden.py`). SQL stays the source of truth; nothing here serves a request. The
 * flag-off shadow (`../rankedReadsShadow.ts`) compares a twin against the Postgres read.
 *
 * Functions covered: trending.claims_and_debates, debate_links, current_agendas, agenda_contents, current_agenda_listings,
 * newest_listings, claim_listings, entity_listings, entity_topic_listings, public.current_debate_agendas and
 * public.topic_suggestions_for_spaces.
 *
 * Fidelity notes (each is a place the SQL is subtle, and each is exercised by the golden grid):
 *  - `position_order`: bytewise compare of `lower(pos) || ' ' || swapcase(pos)`, NULL last. ASCII-only case folding, as in the
 *    SQL's translate() and a C-locale lower().
 *  - `value_date`: ASCII `\d{4}-\d{2}-\d{2}` prefix of `datetime`, then of `date`, else `datetime_utc` as a New York calendar
 *    date. A matching prefix that is not a real date gives NULL (the SQL's exception handler), it does not fall through.
 *  - dates are `YYYY-MM-DD` strings, which sort as dates; `listed_at` is midnight New York as an instant.
 *  - DISTINCT ON tie rules are reproduced in full; where the SQL leaves a tie unordered (the same entity listed twice on one day
 *    by one agenda in two spaces) the twin takes the first row it sees, and the golden seeds avoid such ties.
 *  - text ordering uses code-unit order, which equals the harness's C collation. A production database on another collation
 *    orders `topic_id`/`agenda_id` uuids the same way (uuids are ASCII hex), so only `created_at` (digits) and names are touched.
 */

export const TYPES = "8f151ba4-de20-4e3c-9cb4-99ddf96f48f1"
export const CLAIM = "96f859ef-a1ca-4b22-9372-c86ad58b694b"
export const DEBATE = "fd51f935-2063-4617-be39-7b672b23364c"
export const AGENDA = "79e3757b-2630-492c-9d3b-d73a78d45893"
export const DATE = "52665f3e-fb7d-48d5-8b6b-abb21b0d36db"
export const NAME = "a126ca53-0c8e-48d5-b888-82c734c38935"
export const BLOCKS = "beaba5cb-a677-41a8-b353-77030613fc70"
export const CLAIMS = "e614cce1-c4ce-4586-8304-fd1237119eb2"
export const DEBATES = "b96bf701-a399-430d-a072-f5e910cdeda9"
export const TOPICS = "806d52bc-27e9-4c91-93c0-57978b093351"
export const COLLECTION_ITEM = "a99f9ce1-2ffa-4dac-8c61-f6310d46064a"
export const TIME_ZONE = "America/New_York"
export const CURRENT_DAYS = 6
export const CLAIM_SOURCES = ["block_item", "agenda_claims"]

export interface EntityRow {
	id: string
	created_at: string
}
export interface SpaceRow {
	id: string
	type: string
	topic_id: string | null
}
export interface RelationRow {
	id: string
	type_id: string
	from_entity_id: string
	to_entity_id: string
	position: string | null
	space_id: string
}
export interface ValueRow {
	id: string
	property_id: string
	entity_id: string
	space_id: string
	text: string | null
	datetime_utc: string | null
	datetime: string | null
	date: string | null
}
/** A `trending.agenda_listings` row. */
export interface ListingRow {
	source: string
	space_id: string
	agenda_id: string
	entity_id: string
	listed_on: string
}
/** A `public.space_topic_suggestions` row. */
export interface SuggestionRow {
	space_id: string
	topic_id: string
	name_key: string
	links: number
	rank: number
}
export interface Graph {
	entities: EntityRow[]
	spaces: SpaceRow[]
	relations: RelationRow[]
	values: ValueRow[]
	listings: ListingRow[]
	suggestions: SuggestionRow[]
}

export interface ContentRow {
	agenda_id: string
	space_id: string
	listed_on: string
	source: string
	section_id: string | null
	section_position: number | null
	entity_id: string
	item_position: number | null
}
export interface CurrentDebateAgendaRow {
	space_id: string
	agenda_id: string
	listed_on: string
	/** ISO instant, midnight New York of `listed_on`. */
	listed_at: string
	is_current: boolean
	source: string
	section_id: string | null
	section_name: string | null
	section_topic_id: string | null
	section_position: number | null
	entity_id: string
	item_position: number | null
	last_listed_on: string | null
}

// ---- helpers -------------------------------------------------------------------------------------------------------------

/** `trending.position_order`: the bytes the SQL sorts a fractional position by (NULL stays null). */
export function positionOrder(pos: string | null): Buffer | null {
	if (pos === null) return null
	const lower = pos.replace(/[A-Z]/g, (c) => c.toLowerCase())
	const swapped = pos.replace(/[A-Za-z]/g, (c) => (c >= "a" ? c.toUpperCase() : c.toLowerCase()))
	return Buffer.from(`${lower} ${swapped}`, "utf8")
}

/** ASC with NULLS LAST over buffers. */
function cmpBuf(a: Buffer | null, b: Buffer | null): number {
	if (a === null) return b === null ? 0 : 1
	if (b === null) return -1
	return Buffer.compare(a, b)
}
function cmpStr(a: string, b: string): number {
	return a < b ? -1 : a > b ? 1 : 0
}
/** ASC with NULLS LAST over numbers. */
function cmpNum(a: number | null, b: number | null): number {
	if (a === null) return b === null ? 0 : 1
	if (b === null) return -1
	return a - b
}

function validDate(s: string): boolean {
	const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
	if (!m) return false
	const y = Number(m[1])
	const mo = Number(m[2])
	const d = Number(m[3])
	if (y < 1 || mo < 1 || mo > 12 || d < 1) return false
	return d <= new Date(Date.UTC(y, mo, 0)).getUTCDate()
}

const nyFormat = new Intl.DateTimeFormat("en-US", {
	timeZone: TIME_ZONE,
	hourCycle: "h23",
	year: "numeric",
	month: "2-digit",
	day: "2-digit",
	hour: "2-digit",
	minute: "2-digit",
	second: "2-digit",
})
function nyParts(ms: number): {date: string; hour: number; minute: number; second: number} {
	const p: Record<string, string> = {}
	for (const part of nyFormat.formatToParts(new Date(ms))) p[part.type] = part.value
	return {
		date: `${p.year}-${p.month}-${p.day}`,
		hour: Number(p.hour),
		minute: Number(p.minute),
		second: Number(p.second),
	}
}

/** `trending.value_date`: the calendar date a Date value stands for, or null. */
export function valueDate(v: {
	datetime_utc: string | null
	datetime: string | null
	date: string | null
}): string | null {
	const prefix = /^\d{4}-\d{2}-\d{2}/
	for (const s of [v.datetime, v.date]) {
		if (s !== null && prefix.test(s)) {
			const d = s.slice(0, 10)
			return validDate(d) ? d : null
		}
	}
	if (v.datetime_utc === null) return null
	const ms = Date.parse(v.datetime_utc)
	return Number.isNaN(ms) ? null : nyParts(ms).date
}

/** `date + n` days. */
export function addDays(date: string, n: number): string {
	const [y, m, d] = date.split("-").map(Number)
	return new Date(Date.UTC(y!, m! - 1, d! + n)).toISOString().slice(0, 10)
}

/** Midnight New York of `date`, as an ISO instant (`listed_on::timestamp AT TIME ZONE trending.time_zone()`). */
export function listedAt(date: string): string {
	const [y, m, d] = date.split("-").map(Number)
	const base = Date.UTC(y!, m! - 1, d!)
	for (const off of [4, 5]) {
		const ms = base + off * 3_600_000
		const p = nyParts(ms)
		if (p.date === date && p.hour === 0 && p.minute === 0 && p.second === 0) return new Date(ms).toISOString()
	}
	throw new Error(`no New York midnight for ${date}`)
}

/** The `name_key` the suggestions table and `topic_suggestions_for_spaces` share. */
export function nameKey(text: string): string {
	return text
		.toLowerCase()
		.replace(/^ +| +$/g, "")
		.replace(/[ \t\n\r\f\v]+/g, " ")
}

function distinctOn<T>(rows: T[], key: (r: T) => string, cmp: (a: T, b: T) => number): T[] {
	const best = new Map<string, T>()
	for (const r of rows) {
		const k = key(r)
		const cur = best.get(k)
		if (cur === undefined || cmp(r, cur) < 0) best.set(k, r)
	}
	return [...best.values()]
}

/** Number rows within partitions: `row_number() OVER (PARTITION BY part ORDER BY cmp)`, or dense_rank with `dense`. */
function numberWithin<T>(
	rows: T[],
	part: (r: T) => string,
	cmp: (a: T, b: T) => number,
	dense: boolean,
): Map<T, number> {
	const groups = new Map<string, T[]>()
	for (const r of rows) {
		const k = part(r)
		const g = groups.get(k)
		if (g) g.push(r)
		else groups.set(k, [r])
	}
	const out = new Map<T, number>()
	for (const g of groups.values()) {
		g.sort(cmp)
		let n = 0
		for (let i = 0; i < g.length; i++) {
			if (!dense) n = i + 1
			else if (i === 0 || cmp(g[i - 1]!, g[i]!) !== 0) n++
			out.set(g[i]!, n)
		}
	}
	return out
}

const K = (...parts: string[]) => parts.join("|")

// ---- the twin ------------------------------------------------------------------------------------------------------------

export class Trending {
	private readonly relsFrom = new Map<string, RelationRow[]>()
	private readonly valsByEntity = new Map<string, ValueRow[]>()
	private readonly daoSpaces = new Set<string>()
	private readonly created = new Map<string, string>()
	private readonly orders = new Map<RelationRow, Buffer | null>()

	/** `today` is `trending.today()`: the New York calendar date now. */
	constructor(
		private readonly g: Graph,
		readonly today: string,
	) {
		for (const r of g.relations) {
			const l = this.relsFrom.get(r.from_entity_id)
			if (l) l.push(r)
			else this.relsFrom.set(r.from_entity_id, [r])
			this.orders.set(r, positionOrder(r.position))
		}
		for (const v of g.values) {
			const l = this.valsByEntity.get(v.entity_id)
			if (l) l.push(v)
			else this.valsByEntity.set(v.entity_id, [v])
		}
		for (const s of g.spaces) if (s.type === "DAO") this.daoSpaces.add(s.id)
		for (const e of g.entities) this.created.set(e.id, e.created_at)
	}

	private rels(from: string, space?: string): RelationRow[] {
		const all = this.relsFrom.get(from) ?? []
		return space === undefined ? all : all.filter((r) => r.space_id === space)
	}
	private order(r: RelationRow): Buffer | null {
		return this.orders.get(r) ?? null
	}
	/** ORDER BY position_order(position) NULLS LAST, id. */
	private cmpRel = (a: RelationRow, b: RelationRow): number =>
		cmpBuf(this.order(a), this.order(b)) || cmpStr(a.id, b.id)

	claimsAndDebates(ids: string[]): {entity_id: string; is_claim: boolean; is_debate: boolean}[] {
		const out: {entity_id: string; is_claim: boolean; is_debate: boolean}[] = []
		for (const id of new Set(ids)) {
			let seen = false
			let isClaim = false
			let isDebate = false
			for (const r of this.rels(id)) {
				if (r.type_id !== TYPES || (r.to_entity_id !== CLAIM && r.to_entity_id !== DEBATE)) continue
				seen = true
				isClaim ||= r.to_entity_id === CLAIM
				isDebate ||= r.to_entity_id === DEBATE
			}
			if (seen) out.push({entity_id: id, is_claim: isClaim, is_debate: isDebate})
		}
		return out
	}

	debateLinks(claimIds: string[], debateIds: string[]): {debate_id: string; claim_id: string}[] {
		const claims = new Set(claimIds)
		const debates = new Set(debateIds)
		const out = new Map<string, {debate_id: string; claim_id: string}>()
		for (const r of this.g.relations) {
			if (r.type_id !== CLAIMS) continue
			if (!claims.has(r.to_entity_id) && !debates.has(r.from_entity_id)) continue
			if (!this.daoSpaces.has(r.space_id)) continue
			const typed = this.rels(r.from_entity_id, r.space_id).some(
				(t) => t.type_id === TYPES && t.to_entity_id === DEBATE,
			)
			if (typed)
				out.set(K(r.from_entity_id, r.to_entity_id), {debate_id: r.from_entity_id, claim_id: r.to_entity_id})
		}
		return [...out.values()]
	}

	currentAgendas(): {agenda_id: string; space_id: string; listed_on: string}[] {
		const best = new Map<string, {agenda_id: string; space_id: string; listed_on: string}>()
		for (const ty of this.g.relations) {
			if (ty.to_entity_id !== AGENDA || ty.type_id !== TYPES || !this.daoSpaces.has(ty.space_id)) continue
			for (const v of this.valsByEntity.get(ty.from_entity_id) ?? []) {
				if (v.space_id !== ty.space_id || v.property_id !== DATE) continue
				const d = valueDate(v)
				if (d === null) continue
				const k = K(ty.from_entity_id, ty.space_id)
				const cur = best.get(k)
				if (cur === undefined) best.set(k, {agenda_id: ty.from_entity_id, space_id: ty.space_id, listed_on: d})
				else if (d > cur.listed_on) cur.listed_on = d
			}
		}
		return [...best.values()]
	}

	agendaContents(spaceIds: string[] | null = null, since: string | null = null): ContentRow[] {
		const spaces = spaceIds === null ? null : new Set(spaceIds)
		const agendas = this.currentAgendas().filter(
			(a) => (spaces === null || spaces.has(a.space_id)) && (since === null || a.listed_on >= since),
		)
		// links: each target once per (agenda, space, type), at its first position.
		const linkTypes = new Set([BLOCKS, CLAIMS, DEBATES, TOPICS])
		interface Link {
			agenda_id: string
			space_id: string
			listed_on: string
			type_id: string
			to_entity_id: string
			link_order: Buffer | null
			link_rel: string
		}
		const links: Link[] = []
		for (const a of agendas) {
			const picked = distinctOn(
				this.rels(a.agenda_id, a.space_id).filter((r) => linkTypes.has(r.type_id)),
				(r) => K(r.type_id, r.to_entity_id),
				this.cmpRel,
			)
			for (const r of picked) {
				links.push({
					agenda_id: a.agenda_id,
					space_id: a.space_id,
					listed_on: a.listed_on,
					type_id: r.type_id,
					to_entity_id: r.to_entity_id,
					link_order: this.order(r),
					link_rel: r.id,
				})
			}
		}
		// block items: each block's items, an item once per block at its first position.
		interface Item {
			agenda_id: string
			space_id: string
			listed_on: string
			section_id: string
			section_order: Buffer | null
			section_rel: string
			entity_id: string
			item_order: Buffer | null
			item_rel: string
		}
		const items: Item[] = []
		for (const l of links) {
			if (l.type_id !== BLOCKS) continue
			const picked = distinctOn(
				this.rels(l.to_entity_id, l.space_id).filter((r) => r.type_id === COLLECTION_ITEM),
				(r) => r.to_entity_id,
				this.cmpRel,
			)
			for (const r of picked) {
				items.push({
					agenda_id: l.agenda_id,
					space_id: l.space_id,
					listed_on: l.listed_on,
					section_id: l.to_entity_id,
					section_order: l.link_order,
					section_rel: l.link_rel,
					entity_id: r.to_entity_id,
					item_order: this.order(r),
					item_rel: r.id,
				})
			}
		}
		const kinds = this.claimsAndDebates([
			...items.map((i) => i.entity_id),
			...links.filter((l) => l.type_id === CLAIMS || l.type_id === DEBATES).map((l) => l.to_entity_id),
		])
		const claims = new Set(kinds.filter((k) => k.is_claim).map((k) => k.entity_id))
		const debates = new Set(kinds.filter((k) => k.is_debate).map((k) => k.entity_id))

		const blockItems = items.filter((i) => claims.has(i.entity_id))
		const sectionRank = numberWithin(
			blockItems,
			(i) => K(i.agenda_id, i.space_id),
			(a, b) => cmpBuf(a.section_order, b.section_order) || cmpStr(a.section_rel, b.section_rel),
			true,
		)
		const itemRank = numberWithin(
			blockItems,
			(i) => K(i.agenda_id, i.space_id, i.section_id),
			(a, b) => cmpBuf(a.item_order, b.item_order) || cmpStr(a.item_rel, b.item_rel),
			false,
		)
		const out: ContentRow[] = blockItems.map((i) => ({
			agenda_id: i.agenda_id,
			space_id: i.space_id,
			listed_on: i.listed_on,
			source: "block_item",
			section_id: i.section_id,
			section_position: sectionRank.get(i)!,
			entity_id: i.entity_id,
			item_position: itemRank.get(i)!,
		}))
		const linkRows = links.filter(
			(l) =>
				l.type_id === TOPICS ||
				(l.type_id === CLAIMS && claims.has(l.to_entity_id)) ||
				(l.type_id === DEBATES && debates.has(l.to_entity_id)),
		)
		const linkRank = numberWithin(
			linkRows,
			(l) => K(l.agenda_id, l.space_id, l.type_id),
			(a, b) => cmpBuf(a.link_order, b.link_order) || cmpStr(a.link_rel, b.link_rel),
			false,
		)
		for (const l of linkRows) {
			out.push({
				agenda_id: l.agenda_id,
				space_id: l.space_id,
				listed_on: l.listed_on,
				source:
					l.type_id === CLAIMS ? "agenda_claims" : l.type_id === DEBATES ? "agenda_debates" : "agenda_topics",
				section_id: null,
				section_position: null,
				entity_id: l.to_entity_id,
				item_position: linkRank.get(l)!,
			})
		}
		return out
	}

	currentAgendaListings(): {
		agenda_id: string
		space_id: string
		entity_id: string
		listed_on: string
		source: string
	}[] {
		const out = new Map<
			string,
			{agenda_id: string; space_id: string; entity_id: string; listed_on: string; source: string}
		>()
		for (const c of this.agendaContents()) {
			out.set(K(c.agenda_id, c.space_id, c.entity_id, c.listed_on, c.source), {
				agenda_id: c.agenda_id,
				space_id: c.space_id,
				entity_id: c.entity_id,
				listed_on: c.listed_on,
				source: c.source,
			})
		}
		return [...out.values()]
	}

	/** Reads the stored `trending.agenda_listings` rows, not the live agendas. */
	newestListings(
		ids: string[],
		sources: string[],
	): {entity_id: string; last_listed_on: string; agenda_id: string; space_id: string}[] {
		const want = new Set(ids)
		const src = new Set(sources)
		const rows = this.g.listings.filter(
			(l) => want.has(l.entity_id) && src.has(l.source) && l.listed_on <= this.today,
		)
		return distinctOn(
			rows,
			(l) => l.entity_id,
			(a, b) => cmpStr(b.listed_on, a.listed_on) || cmpStr(a.agenda_id, b.agenda_id),
		).map((l) => ({
			entity_id: l.entity_id,
			last_listed_on: l.listed_on,
			agenda_id: l.agenda_id,
			space_id: l.space_id,
		}))
	}

	claimListings(ids: string[]): {claim_id: string; last_listed_on: string; agenda_id: string; space_id: string}[] {
		return this.newestListings(ids, CLAIM_SOURCES).map((l) => ({
			claim_id: l.entity_id,
			last_listed_on: l.last_listed_on,
			agenda_id: l.agenda_id,
			space_id: l.space_id,
		}))
	}

	entityListings(
		ids: string[],
	): {entity_id: string; last_listed_on: string; agenda_id: string; own_claim_listing: boolean}[] {
		const k = this.claimsAndDebates(ids)
		const debateIds = k.filter((x) => x.is_debate).map((x) => x.entity_id)
		const claimOf = new Map<string, {entity_id: string; claim_id: string}>()
		for (const x of k)
			if (x.is_claim) claimOf.set(K(x.entity_id, x.entity_id), {entity_id: x.entity_id, claim_id: x.entity_id})
		for (const dl of this.debateLinks([], debateIds)) {
			claimOf.set(K(dl.debate_id, dl.claim_id), {entity_id: dl.debate_id, claim_id: dl.claim_id})
		}
		const byClaim = new Map(
			this.claimListings([...claimOf.values()].map((c) => c.claim_id)).map((l) => [l.claim_id, l]),
		)
		interface L {
			entity_id: string
			last_listed_on: string
			agenda_id: string
			own: boolean
		}
		const listings: L[] = []
		for (const co of claimOf.values()) {
			const l = byClaim.get(co.claim_id)
			if (l)
				listings.push({
					entity_id: co.entity_id,
					last_listed_on: l.last_listed_on,
					agenda_id: l.agenda_id,
					own: co.claim_id === co.entity_id,
				})
		}
		for (const dl of this.newestListings(debateIds, ["agenda_debates"])) {
			listings.push({
				entity_id: dl.entity_id,
				last_listed_on: dl.last_listed_on,
				agenda_id: dl.agenda_id,
				own: false,
			})
		}
		return distinctOn(
			listings,
			(x) => x.entity_id,
			(a, b) =>
				cmpStr(b.last_listed_on, a.last_listed_on) ||
				Number(a.own) - Number(b.own) ||
				cmpStr(a.agenda_id, b.agenda_id),
		).map((x) => ({
			entity_id: x.entity_id,
			last_listed_on: x.last_listed_on,
			agenda_id: x.agenda_id,
			own_claim_listing: x.own,
		}))
	}

	entityTopicListings(ids: string[]): {entity_id: string; topic_id: string; listed_on: string}[] {
		const topicListings = new Map<string, ListingRow[]>()
		for (const l of this.g.listings) {
			if (l.source !== "agenda_topics" || l.listed_on > this.today) continue
			const a = topicListings.get(l.entity_id)
			if (a) a.push(l)
			else topicListings.set(l.entity_id, [l])
		}
		const rows: {entity_id: string; topic_id: string; listed_on: string}[] = []
		for (const k of this.claimsAndDebates(ids)) {
			for (const tr of this.rels(k.entity_id)) {
				if (tr.type_id !== TOPICS || !this.daoSpaces.has(tr.space_id)) continue
				for (const tl of topicListings.get(tr.to_entity_id) ?? []) {
					rows.push({entity_id: k.entity_id, topic_id: tl.entity_id, listed_on: tl.listed_on})
				}
			}
		}
		return distinctOn(
			rows,
			(r) => r.entity_id,
			(a, b) => cmpStr(b.listed_on, a.listed_on) || cmpStr(a.topic_id, b.topic_id),
		)
	}

	currentDebateAgendas(spaceIds: string[] | null = null, earlierDays: number | null = 0): CurrentDebateAgendaRow[] {
		const today = this.today
		const earlier = Math.min(Math.max(earlierDays ?? 0, 0), 31)
		const window = addDays(today, -Math.max(CURRENT_DAYS, earlier))
		const asked = spaceIds === null ? null : new Set(spaceIds)

		interface Ranked {
			agenda_id: string
			space_id: string
			listed_on: string
			created: bigint | null
			recency: number
		}
		const cands: Ranked[] = []
		for (const a of this.currentAgendas()) {
			const created = this.created.get(a.agenda_id)
			if (created === undefined) continue // JOIN entities
			if (asked !== null && !asked.has(a.space_id)) continue
			if (a.listed_on > today || a.listed_on < window) continue
			cands.push({...a, created: /^[0-9]+$/.test(created) ? BigInt(created) : null, recency: 0})
		}
		const cmpRecency = (a: Ranked, b: Ranked): number => {
			if (a.listed_on !== b.listed_on) return cmpStr(b.listed_on, a.listed_on)
			if (a.created !== b.created) {
				if (a.created === null) return 1
				if (b.created === null) return -1
				return a.created > b.created ? -1 : 1
			}
			return cmpStr(b.agenda_id, a.agenda_id)
		}
		for (const [r, n] of numberWithin(cands, (c) => c.space_id, cmpRecency, false)) r.recency = n

		const freshSpace = new Set(
			cands.filter((r) => r.recency === 1 && r.listed_on >= addDays(today, -CURRENT_DAYS)).map((r) => r.space_id),
		)
		const agendas = cands.filter((r) => asked !== null || freshSpace.has(r.space_id))
		const currentSet = agendas.filter((a) => a.recency === 1 && a.listed_on >= addDays(today, -CURRENT_DAYS))
		const currentBySpace = new Map(currentSet.map((c) => [c.space_id, c]))

		// space order: as asked, or freshest current agenda first.
		const askedIndex = new Map<string, number>()
		;(spaceIds ?? []).forEach((id, i) => {
			if (!askedIndex.has(id)) askedIndex.set(id, i + 1)
		})
		const spaceN = new Map<string, number>()
		const orderedSpaces = [...new Set(agendas.map((a) => a.space_id))].sort((x, y) => {
			const ax = askedIndex.get(x) ?? null
			const ay = askedIndex.get(y) ?? null
			const c = cmpNum(ax, ay)
			if (c !== 0) return c
			const lx = currentBySpace.get(x)?.listed_on ?? null
			const ly = currentBySpace.get(y)?.listed_on ?? null
			if (lx !== ly) {
				if (lx === null) return 1
				if (ly === null) return -1
				return cmpStr(ly, lx)
			}
			return cmpStr(x, y)
		})
		orderedSpaces.forEach((s, i) => spaceN.set(s, i + 1))

		interface C extends ContentRow {
			recency: number
			is_current: boolean
		}
		const agendaByKey = new Map(agendas.map((a) => [K(a.agenda_id, a.space_id), a]))
		const contents: C[] = []
		for (const c of this.agendaContents([...new Set(agendas.map((a) => a.space_id))], window)) {
			const ag = agendaByKey.get(K(c.agenda_id, c.space_id))
			if (ag) contents.push({...c, recency: ag.recency, is_current: currentSet.includes(ag)})
		}
		const currentRows = contents.filter((c) => c.is_current)
		const taken = new Set(
			currentRows.filter((c) => c.source === "block_item").map((c) => K(c.space_id, c.entity_id)),
		)
		const earlierFloor = addDays(today, -earlier)
		const earlierFirst =
			earlier > 0
				? distinctOn(
						contents.filter(
							(c) =>
								c.source === "block_item" &&
								c.listed_on >= earlierFloor &&
								!taken.has(K(c.space_id, c.entity_id)),
						),
						(c) => K(c.space_id, c.entity_id),
						(a, b) =>
							cmpStr(b.listed_on, a.listed_on) ||
							a.recency - b.recency ||
							cmpNum(a.section_position, b.section_position) ||
							cmpNum(a.item_position, b.item_position),
					)
				: []
		const sectionRank = numberWithin(
			earlierFirst,
			(e) => K(e.space_id, e.agenda_id),
			(a, b) => cmpNum(a.section_position, b.section_position),
			true,
		)
		const itemRank = numberWithin(
			earlierFirst,
			(e) => K(e.space_id, e.agenda_id, e.section_id ?? ""),
			(a, b) => cmpNum(a.item_position, b.item_position),
			false,
		)
		const earlierRows: C[] = earlierFirst.map((e) => ({
			...e,
			section_position: sectionRank.get(e)!,
			item_position: itemRank.get(e)!,
			is_current: false,
		}))
		const picked = [...currentRows, ...earlierRows]

		const listed = new Map(
			this.entityListings([
				...new Set(picked.filter((p) => p.source !== "agenda_topics").map((p) => p.entity_id)),
			]).map((l) => [l.entity_id, l.last_listed_on]),
		)
		const maxOn = new Map<string, string>()
		for (const p of picked) {
			if (p.source === "agenda_topics") continue
			const cur = maxOn.get(p.entity_id)
			if (cur === undefined || p.listed_on > cur) maxOn.set(p.entity_id, p.listed_on)
		}
		const sourceRank = (s: string): number =>
			s === "block_item" ? 0 : s === "agenda_claims" ? 1 : s === "agenda_debates" ? 2 : 3
		const rows = picked.filter((p) => spaceN.has(p.space_id))
		rows.sort(
			(a, b) =>
				spaceN.get(a.space_id)! - spaceN.get(b.space_id)! ||
				Number(b.is_current) - Number(a.is_current) ||
				cmpStr(b.listed_on, a.listed_on) ||
				a.recency - b.recency ||
				sourceRank(a.source) - sourceRank(b.source) ||
				cmpNum(a.section_position, b.section_position) ||
				cmpNum(a.item_position, b.item_position),
		)
		return rows.map((p) => {
			let sectionName: string | null = null
			let sectionTopic: string | null = null
			if (p.section_id !== null) {
				sectionName =
					(this.valsByEntity.get(p.section_id) ?? []).find(
						(v) => v.space_id === p.space_id && v.property_id === NAME,
					)?.text ?? null
				sectionTopic =
					this.rels(p.section_id, p.space_id)
						.filter((r) => r.type_id === TOPICS)
						.sort(this.cmpRel)[0]?.to_entity_id ?? null
			}
			let last: string | null = null
			if (p.source !== "agenda_topics") {
				const a = listed.get(p.entity_id)
				const b = maxOn.get(p.entity_id)!
				last = a !== undefined && a > b ? a : b
			}
			return {
				space_id: p.space_id,
				agenda_id: p.agenda_id,
				listed_on: p.listed_on,
				listed_at: listedAt(p.listed_on),
				is_current: p.is_current,
				source: p.source,
				section_id: p.section_id,
				section_name: sectionName,
				section_topic_id: sectionTopic,
				section_position: p.section_position,
				entity_id: p.entity_id,
				item_position: p.item_position,
				last_listed_on: last,
			}
		})
	}

	topicSuggestionsForSpaces(spaceIds: string[]): EntityRow[] {
		const asked = new Set(spaceIds)
		const own = new Set<string>()
		for (const sp of this.g.spaces) {
			if (!asked.has(sp.id) || sp.topic_id === null) continue
			const names = (this.valsByEntity.get(sp.topic_id) ?? [])
				.filter((v) => v.property_id === NAME && (v.text ?? "").replace(/^ +| +$/g, "") !== "")
				.sort((a, b) => cmpStr(a.space_id, b.space_id))
			if (names[0]) own.add(nameKey(names[0].text!))
		}
		const picked = distinctOn(
			this.g.suggestions.filter((s) => asked.has(s.space_id) && !own.has(s.name_key)),
			(s) => s.name_key,
			(a, b) => a.rank - b.rank || b.links - a.links || cmpStr(a.topic_id, b.topic_id),
		)
		picked.sort((a, b) => a.rank - b.rank || b.links - a.links || cmpStr(a.topic_id, b.topic_id))
		const entities = new Map(this.g.entities.map((e) => [e.id, e]))
		return picked.flatMap((p) => {
			const e = entities.get(p.topic_id)
			return e ? [{id: e.id, created_at: e.created_at}] : []
		})
	}
}
